'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// VARIABLES //

var mgf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( mgf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof mgf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', opts, function test( t ) {
	var y = mgf( NaN, 2.0, 3.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	y = mgf( 0.1, NaN, 3.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	y = mgf( 0.1, 2.0, NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided a nonpositive `mu`, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = mgf( 0.1, 0.0, 3.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 0.1, -1.0, 3.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 0.1, NINF, 3.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 0.1, NINF, PINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 0.1, NINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 0.1, NINF, NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a nonpositive `lambda`, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = mgf( 0.1, 2.0, 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 0.1, 2.0, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 0.1, 2.0, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 0.1, PINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 0.1, NINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 0.1, NaN, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a value of x > lambda/(2*mu^2), the function returns `NaN`', opts, function test( t ) {
	var y;

	y = mgf( 0.9, 1.0, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 5.0, 1.0, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the function evaluates the MGF for `x` given positive `mu` and lambda', opts, function test( t ) {
	var expected;
	var lambda;
	var mu;
	var x;
	var y;
	var i;

	expected = data.expected;
	x = data.x;
	mu = data.mu;
	lambda = data.lambda;
	for ( i = 0; i < x.length; i++ ) {
		y = mgf( x[ i ], mu[ i ], lambda[ i ] );
		if ( expected[ i ] !== null ) {
			t.ok( isAlmostSameValue( y, expected[ i ], 150 ), 'within tolerance. x: '+x[ i ]+'. mu: '+mu[ i ]+'. lambda: '+lambda[ i ]+'. y: '+y+'. E: '+expected[ i ]+'.' );
		}
	}
	t.end();
});
